def hasValueCycle(grid):
    rows, cols = len(grid), len(grid[0])
    seen = [[False] * cols for _ in range(rows)]
    for r in range(rows):
        for c in range(cols):
            if seen[r][c]:
                continue
            seen[r][c] = True
            stack = [(r, c, -1, -1)]
            while stack:
                y, x, py, px = stack.pop()
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if not (0 <= ny < rows and 0 <= nx < cols) or grid[ny][nx] != grid[y][x]:
                        continue
                    if (ny, nx) == (py, px):
                        continue
                    if seen[ny][nx]:
                        return True
                    seen[ny][nx] = True
                    stack.append((ny, nx, y, x))
    return False
